#include "kloks/midi.hpp"
#include "kloks/osc.hpp"
#include "kloks/test_utils.hpp"
#include <stdexcept>
int main(){using namespace kloks;
 MidiDecoder d;const auto first=d.decode({0x90,60,127});require(first.status==0x90&&first.data.size()==2,"MIDI note");const auto running=d.decode({61,100});require(running.status==0x90&&running.data[0]==61,"running status");require(midi_encode(first)==std::vector<std::uint8_t>({0x90,60,127}),"midi roundtrip");require_throws<std::invalid_argument>([&]{d.decode({0x90,61});});require_throws<std::invalid_argument>([]{(void)midi_encode({0x90,{200,1}});});require_throws<std::invalid_argument>([]{(void)midi_encode({0xF0,{1,2}});});require(midi_encode({0xF0,{1,2,0xF7}})==std::vector<std::uint8_t>({0xF0,1,2,0xF7}),"sysex");
 struct MH:MidiHost{std::string port;std::vector<std::uint8_t> packet;void send(const std::string& p,const std::vector<std::uint8_t>& data)override{port=p;packet=data;}} mh;MidiRouter router(mh);router.route("keyboard","usb0");router.send("keyboard",first);require(mh.port=="usb0"&&mh.packet.size()==3,"host MIDI");require_throws<std::out_of_range>([&]{router.send("missing",first);});
 OscMessage m{"/music/note",{std::int32_t(42),1.5f,std::string("abc"),OscBlob{1,2,3},true,false,std::monostate{}}};auto bytes=osc_encode(m);auto decoded=osc_decode(bytes);require(decoded.address==m.address&&decoded.arguments.size()==7,"OSC count");require(std::get<std::int32_t>(decoded.arguments[0])==42,"OSC integer");require(std::get<std::string>(decoded.arguments[2])=="abc","OSC string");require(std::get<OscBlob>(decoded.arguments[3]).size()==3,"OSC blob");require(std::get<bool>(decoded.arguments[4]),"OSC true");require(!std::get<bool>(decoded.arguments[5]),"OSC false");require_throws<std::invalid_argument>([]{(void)osc_encode(OscMessage{"invalid",{}});});auto truncated=bytes;truncated.pop_back();require_throws<std::invalid_argument>([&]{(void)osc_decode(truncated);});
 OscBundle bundle{0x123456789abcdef0ULL,{m,{"/empty",{}}}};auto bundled=osc_decode_bundle(osc_encode(bundle));require(bundled.timetag==bundle.timetag&&bundled.messages.size()==2,"OSC bundle");struct OH:OscHost{std::size_t sent=0;void send(const std::string&,const OscBlob& p)override{sent=p.size();}}oh;OscRouter osc(oh);osc.send("udp://127.0.0.1:9000",m);require(oh.sent==bytes.size(),"OSC injected host");
}
